#include <cstddef>
#include <utility>
#include <vector>

template <typename T>
class Stack
{
public:
    void push(T value);

    bool pop()
    {
        if (m_items.empty())
        {
            return false;
        }
        m_items.pop_back();
        return true;
    }

    const T& top() const { return m_items.back(); }
    bool empty() const { return m_items.empty(); }
    std::size_t size() const { return m_items.size(); }

private:
    std::vector<T> m_items{};
};

template <typename T>
void Stack<T>::push(T value)
{
    m_items.push_back(std::move(value));
}

unitTests:
TEST("ints") { Stack<int> s{}; CHECK(s.empty()); s.push(1); s.push(2); CHECK_EQ(s.top(), 2); CHECK_EQ(s.size(), 2u); CHECK(s.pop()); CHECK_EQ(s.top(), 1); CHECK(s.pop()); CHECK(!s.pop()); }
TEST("strings") { Stack<std::string> s{}; s.push("a"); s.push("b"); CHECK_EQ(s.top(), "b"); }
TEST("move-only types work too") { Stack<std::unique_ptr<int>> s{}; s.push(std::make_unique<int>(7)); CHECK_EQ(*s.top(), 7); CHECK(s.pop()); CHECK(s.empty()); }

